class ToastService{constructor(){this.container=null;this.toasts=new Map();this.defaultDuration=5000;this.maxToasts=5;this.init();}init(){if(!this.container){this.container=document.createElement('div');this.container.className='toast-container';this.container.setAttribute('role','region');this.container.setAttribute('aria-label','Notifications');this.container.setAttribute('aria-live','polite');document.body.appendChild(this.container);}}show(options={}){const{type='info',title,message,duration=this.defaultDuration,persistent=false,actions=[],id=this.generateId()}=options;if(this.toasts.size >=this.maxToasts){const firstToast=this.toasts.keys().next().value;this.hide(firstToast);}const toast=this.createToast({id,type,title,message,duration,persistent,actions});this.container.appendChild(toast);this.toasts.set(id,toast);requestAnimationFrame(()=>{toast.classList.add('show');});if(!persistent && duration > 0){setTimeout(()=>{this.hide(id);},duration);}return id;}hide(id){const toast=this.toasts.get(id);if(!toast)return;toast.classList.add('hide');toast.classList.remove('show');setTimeout(()=>{if(toast.parentNode){toast.parentNode.removeChild(toast);}this.toasts.delete(id);},200);}hideAll(){this.toasts.forEach((toast,id)=>{this.hide(id);});}createToast({id,type,title,message,duration,persistent,actions}){const toast=document.createElement('div');toast.className=`toast toast-${type}`;toast.setAttribute('role','alert');toast.setAttribute('aria-live','assertive');toast.setAttribute('data-toast-id',id);const icons={success:'✓',error:'✕',warning:'⚠',info:'i',loading:'⟳'};let html=` <div class="toast-icon"> ${icons[type] || icons.info}</div> <div class="toast-content"> ${title ? `<h4 class="toast-title">${title}</h4>`:''}${message ? `<p class="toast-message">${message}</p>`:''}${actions.length > 0 ? this.createActions(actions):''}</div> <button class="toast-close" aria-label="Close notification"> <i class="fas fa-times"></i> </button> `;if(!persistent && duration > 0){html+='<div class="toast-progress"></div>';}toast.innerHTML=html;this.addToastListeners(toast,id);return toast;}createActions(actions){const actionsHtml=actions.map(action=> `<button class="toast-action" data-action="${action.id}"> ${action.label}</button>`).join('');return `<div class="toast-actions">${actionsHtml}</div>`;}addToastListeners(toast,id){const closeBtn=toast.querySelector('.toast-close');closeBtn?.addEventListener('click',()=> this.hide(id));toast.addEventListener('click',(e)=>{if(!e.target.closest('.toast-action')){this.hide(id);}});const actionButtons=toast.querySelectorAll('.toast-action');actionButtons.forEach(btn=>{btn.addEventListener('click',(e)=>{const actionId=e.target.getAttribute('data-action');this.handleAction(id,actionId);});});toast.addEventListener('keydown',(e)=>{if(e.key==='Escape'){this.hide(id);}});}handleAction(toastId,actionId){const event=new CustomEvent('toast-action',{detail:{toastId,actionId}});document.dispatchEvent(event);this.hide(toastId);}generateId(){return `toast-${Date.now()}-${Math.random().toString(36).substr(2,9)}`;}success(title,message,options={}){return this.show({type:'success',title,message,...options});}error(title,message,options={}){return this.show({type:'error',title,message,duration:0,...options});}warning(title,message,options={}){return this.show({type:'warning',title,message,...options});}info(title,message,options={}){return this.show({type:'info',title,message,...options});}loading(title,message,options={}){return this.show({type:'loading',title,message,persistent:true,...options});}update(id,options={}){const toast=this.toasts.get(id);if(!toast)return;const{title,message,type}=options;if(title){const titleEl=toast.querySelector('.toast-title');if(titleEl)titleEl.textContent=title;}if(message){const messageEl=toast.querySelector('.toast-message');if(messageEl)messageEl.textContent=message;}if(type){toast.className=`toast toast-${type}show`;const iconEl=toast.querySelector('.toast-icon');const icons={success:'✓',error:'✕',warning:'⚠',info:'i',loading:'⟳'};if(iconEl && icons[type]){iconEl.textContent=icons[type];}}}showOperation(title,options={}){const loadingId=this.loading(title,'Processing...',options);return{success:(message='Completed successfully')=>{this.hide(loadingId);return this.success(title,message,options);},error:(message='Operation failed')=>{this.hide(loadingId);return this.error(title,message,options);},update:(message)=>{this.update(loadingId,{message});},cancel:()=>{this.hide(loadingId);}};}}const toastService=new ToastService();if(typeof module !=='undefined' && module.exports){module.exports=ToastService;}window.toast=toastService;export default toastService;